-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "participants read shipment events" on public.shipment_events
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM public.shipments s
     JOIN public.orders o ON o.id = s.order_id
  WHERE s.id = shipment_events.shipment_id AND ((( SELECT auth.uid() AS uid)) = o.buyer_id OR (( SELECT auth.uid() AS uid)) = o.seller_id OR ( SELECT public.is_admin() AS is_admin)))));
